{
  "name": "PLC控制粗抽真空泵",
  "name_en": "PLC-Controlled Roughing Pump",
  "manufacturer": "",
  "description": "用于真空系统前级抽气的粗抽真空泵，通过PLC接口进行启停控制，并提供状态信息和压力读回。常用于在高真空泵投入运行前，先将腔体抽至低真空范围。",
  "description_en": "A roughing pump for the foreline stage of a vacuum system, controlled through a PLC interface with start/stop control and status and pressure readback. It is typically used to bring a chamber down to the low-vacuum range before high-vacuum pumps are brought online.",
  "actions": [
    {
      "action_name": "auto-on",
      "description": "开启粗抽真空泵。",
      "description_en": "Turn on the roughing pump."
    },
    {
      "action_name": "auto-off",
      "description": "关闭粗抽真空泵。",
      "description_en": "Turn off the roughing pump."
    },
    {
      "action_name": "auto-info",
      "description": "获取粗抽真空泵的信息或状态摘要。",
      "description_en": "Get roughing pump information or a status summary."
    },
    {
      "action_name": "auto-pressure",
      "description": "获取压力读数。",
      "description_en": "Get the pressure reading."
    },
    {
      "action_name": "auto-egu",
      "description": "获取压力读数的工程单位。",
      "description_en": "Get the engineering units for the pressure reading."
    }
  ],
  "tag_hints": [
    "roughing pump",
    "vacuum pumping",
    "PLC control",
    "foreline vacuum",
    "pressure readback",
    "pump start stop"
  ]
}

